import pickle, os
M=14
A={}
for n in range(M+1):
 for r in range(n+1):
  s={0,2**n}
  if r:
   if n: s |= {2*x for x in A[n-1,min(r,n-1)]}
   for p in range(1,n):
    q=n-p
    for i in range(min(p,r)+1):
     for j in range(min(q,r)+1):
      # xor deg max; and deg sum
      if max(i,j)>r: continue
      for a in A[p,i]:
       for b in A[q,j]:
        s.add(a*2**q+b*2**p-2*a*b)
        if i+j<=r: s.add(a*b)
   if n==1:s.add(1)
  s|={2**n-x for x in s}
  A[n,r]=s
 print(n, len(A[n,n//2]),flush=True)
pickle.dump(A,open('readonce.pkl','wb'))
s=A[14,7]
print('low',sorted(x for x in s if x<=512))
print('missing', sorted(set(range(256,8193,2))-s))

