import itertools,pickle,numpy as np
M=14;N=1<<M;c=7
_,wi=pickle.load(open('triples.pkl','rb'))

def points(basis):
 s=[0]
 for b in basis:s += [x^b for x in s]
 return s

def cosets(basis):
 b={}
 def add(x):
  while x:
   k=x.bit_length()-1
   if k in b:x^=b[k]
   else:b[k]=x;return True
  return False
 for x in basis:add(x)
 comp=[]
 for i in range(M):
  if add(1<<i):comp.append(1<<i)
 p=points(basis)
 return [(z,sum(1<<(x^z) for x in p)) for z in points(comp)]

def construct(spec):
 ab,ac,bc,t,d,mask,trip=spec
 counts={1:c-ab-ac+t-d,2:c-ab-bc+t-d,4:c-ac-bc+t-d,3:ab-t,5:ac-t,6:bc-t,7:t}
 bases=[[],[],[]];idx=0
 for ty,num in counts.items():
  for _ in range(num):
   for i in range(3):
    if ty>>i&1:bases[i].append(1<<idx)
   idx+=1
 for _ in range(d):
  bases[0].append(1<<idx);bases[1].append(1<<(idx+1));bases[2].append(3<<idx);idx+=2
 U=cosets(bases[0])[0][1]
 for v,V in cosets(bases[1]):
  if bool(U&V)!=bool(mask&1):continue
  for w,W in cosets(bases[2]):
   if bool(U&W)!=bool(mask&2) or bool(V&W)!=bool(mask&4):continue
   if bool(U&V&W)!=bool(trip):continue
   return U^V^W
 raise Exception(spec)

att=0;seeds={}
for weight in sorted(wi):
 if weight==0:continue
 f=construct(wi[weight]); assert f.bit_count()==weight
 seeds[weight]=f
 p=np.array([x for x in range(N) if f>>x&1],dtype=np.uint16)
 for coords in itertools.combinations(range(M),7):
  labels=sum(((p>>i)&1)<<j for j,i in enumerate(coords))
  a=np.bincount(labels,minlength=128)
  dp=1<<int(np.minimum(a,128-a).sum())
  for k,num in zip(*np.unique(np.abs(128-2*a),return_counts=True)):
   # bounded subset sum via binary grouping
   k=int(k);num=int(num);step=1
   while num:
    take=min(step,num);dp|=dp<<(take*k);num-=take;step*=2
  att|=dp
 print(weight, 'missing low', [w for w in range(256,338,2) if not(att>>w&1)],flush=True)
pickle.dump((att,seeds),open('alltripcoset.pkl','wb'))
print('missing central',[w for w in range(336,8193,2) if not(att>>w&1)])

